from models.resnet import ResNet


def train(model, loader, optimizer, epochs=10):
    for epoch in range(epochs):
        for batch, labels in loader:
            optimizer.zero_grad()
            loss = model(batch, labels)
            loss.backward()
            optimizer.step()
"}

